\begin{remark}[Practical implementation]\label{rem:head}
Algorithm~\ref{alg:reweight} is implemented entirely through the public \texttt{scaled\_dot\_product\_attention} (SDPA) interface: automatic differentiation applies, and the backward pass again runs \texttt{flash} kernels.
Algorithm~\ref{alg:lse_prescale} is algebraically leaner (no auxiliary key, channel or division) but requires the logits, which the PyTorch backends \texttt{flash}, \texttt{cudnn} and \texttt{memory\_efficient} expose.
In practice, we shift $q$ and $k$ by their common mean to avoid numerical overflow.
Moreover, \texttt{flash} requires half precision (\texttt{fp16} or \texttt{bf16}) and a multiple of $8$ for the dimension of queries, keys and values.
\texttt{Flash} is optimized for $D=C\in \{32, 64, 128\}$ and only works up to $D,C\le 256$.
Both implementations therefore run at dimension $D_{\texttt{reweight}} = \lceil\max(D{+}2, C{+}1)\rceil_8$ and $D_{\texttt{prescale}} = \lceil\max(D, C)\rceil_8$, respectively, where $\lceil\cdot\rceil_8$ rounds up to a multiple of $8$.
\end{remark}

\section{Applications}\label{sec:applications}

\section{Applications}\label{sec:applications}

\paragraph{Maximum mean discrepancy.}
For discrete measures $\mu$ and $\nu$, write their signed difference as
$\sigma \coloneqq \mu-\nu=\sum_{n=1}^N v_n\delta_{k_n}$, with $v\in\R^N$.
Then, their squared maximum mean discrepancy is
\begin{equation}
    \mathrm{MMD}_\tau(\mu,\nu)^2=\iint\Phi_\tau(q,k)\mathrm d\sigma(q)\mathrm d\sigma(k)
  = \sum_{m=1}^N v_m s_m,
  \qquad s_m = \sum_{n=1}^N \Phi_\tau(q_m,k_n)\, v_n.
\end{equation}
Thus, MMD amounts to a kernel sum with $q=k$ and $C=1$, followed by the inner product $v^T s$.

\paragraph{MMD flows and Stein variational gradient descent.}
Particle flows require the gradient of \eqref{eq:ksum} with respect to the query points, namely 
\begin{equation}
    \nabla_{q_m} \sum_{n=1}^N \Phi_\tau(q_m,k_n) v_n
  = \tau\Big(\textstyle\sum_{n=1}^N \Phi_\tau(q_m,k_n) v_n k_n - q_m \sum_{n=1}^N \Phi_\tau(q_m,k_n) v_n\Big),
\end{equation}
which is again a single kernel sum with values $(v_n k_n, v_n)\in\R^{D+1}$.
This is the regime $C= D+1$ and it covers both terms of the SVGD update \cite[Eq.~(8)]{liu2016stein}, whose kernel part has the same form.
Alternatively, plain autograd through Algorithm \ref{alg:reweight} applies.

