\subsection{Proof of Proposition \ref{prop:kappa}}
\label{app:proof:kappa}
\begin{proof}
Since $0< \Phi_\tau(q_m, k_n)\le 1$, the estimate $\kappa(N+1)^{-1} \leq \beta_m \le \kappa$ follows from 
\begin{equation}
\beta_m 
= \frac{\kappa
\e^{ \frac{\tau}{2} \|q_m\|^2}
}{
\e^{\frac{\tau}{2} \|q_m\|^2}{+}\sum_{n=1}^N \e^{\tau q_m^\top k_n -\frac{\tau}{2} \|k_n\|^2}
}
= \frac{\kappa }{1+\sum_{n=1}^N \Phi_\tau(q_m, k_n)}.
\end{equation}
The bound on $\alpha$ follows directly as each $\alpha_m$ is a convex combination of $v$ and $\|\cdot\|_\infty$ is convex.
\end{proof}

